prior_spans:
setReady(false);$('summary').textContent='入力データを読み込んでいます。完了後に操作できます。';
const lessons={T1:'代替なしで選んだ案を、代替需要を含めて評価し直します。商品Aの棚在庫が足りるかを見てください。',T2:'同じ需要で両案の利益を比べます。両方が在庫条件を満たす場合だけ、利益差の割合を計算します。',T3:'需要を棚在庫に合わせて切り詰めた値と、元の需要で条件を満たす値を区別します。需要の定義が違う場合、利益の順位は比較できません。',T4:'Bだけを採用し、Aからの移転を確かめます。Cや未配分へ向かった需要はBへ配り直しません。'};
function flowDiagram(x){const n=x.rows.length,positions=Object.fromEntries(x.rows.map((v,i)=>[v.id,{x:v.k?280:45,y:65+i*75}]));positions['未配分']={x:280,y:65+n*75};const h=130+n*75;return `<svg viewBox="0 0 430 ${h}" role="img" aria-label="棚の外の商品から採用品への需要移転"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#9a5b2c"/></marker></defs><rect x="260" y="15" width="155" height="${n*75+15}" fill="#e0f0e6"/><text x="20" y="30">棚の外</text><text x="275" y="30">採用した商品</text>`+x.flows.filter(v=>v.amount>0).map((v,i)=>{const a=positions[v.source],b=positions[v.target];return `<path d="M${a.x+35} ${a.y} Q${170+i*5} ${(a.y+b.y)/2-20} ${v.target==='未配分'?247:b.x-3} ${b.y}" fill="none" stroke="${v.recovered?'#26776d':'#ac5a38'}" stroke-dasharray="${v.recovered?'0':'5 4'}" marker-end="url(#arrow)"/>`}).join('')+x.rows.map(v=>{const p=positions[v.id];return `<rect x="${p.x}" y="${p.y-18}" width="95" height="36" fill="white" stroke="#456"/><text x="${p.x+5}" y="${p.y+5}">${v.id}：${v.k}面</text>`}).join('')+`<rect x="250" y="${positions['未配分'].y-25}" width="175" height="50" fill="#fff0e7" stroke="#ac5a38"/><text x="260" y="${positions['未配分'].y+5}">未配分（失われる）</text></svg>`;}
if(!x){$('summary').innerHTML='<p class="bad">この採用品を残したまま、現在の幅と在庫条件を満たせる面数の組合せはありません。</p>';for(const id of ['shelf','rows','bars','flows'])$(id).innerHTML='';}else{
$('summary').innerHTML=`<p><strong>${x.feasible?'実行可能':'実行不能'} ／ ${x.feasible?'利益':'名目利益（比較対象外）'} ${fmt(x.profit)}</strong>、使用幅${x.width}/${data.S}。${mode==='no_substitution'?'この欄だけは代替なし需要での評価です。':''}</p>`;
$('shelf').innerHTML=data.S===0?(x.rows.some(v=>v.k)?'<p class="bad">棚幅は0です。選択した商品を置く余地はありません。</p>':'<p>棚幅0：採用商品なし</p>'):x.rows.filter(v=>v.k).map(v=>`<div class="sku" style="width:${100*v.k/data.S}%">${v.id}×${v.k}</div>`).join('');
$('flows').innerHTML=flowDiagram(x)+(x.flows.filter(v=>v.amount>0).map(v=>`<div class="flow ${v.recovered?'':'lost'}">${v.source} → ${v.target}：${fmt(v.amount)}（${v.recovered?'回収':'失われる'}）</div>`).join('')||'<p>代替流入なし。</p>');}
$('comparison').innerHTML='<div class="scroll"><table><thead><tr><th>方式</th><th>面数の組合せ</th><th>同じ需要での金額</th><th>在庫・幅条件</th><th>不足商品</th></tr></thead><tbody>'+[['採用品と面数を一緒に選ぶ',result.oracle.best],['代替なしで選んだ案を再評価',result.reevaluated],['採用品を固定し面数を選び直す',result.fixed_assortment.best]].map(([label,v])=>`<tr><th>${label}</th><td>${v?v.k.join(' / '):'—'}</td><td>${v?fmt(v.profit):'—'}${v&&!v.feasible?'（名目値）':''}</td><td>${v?(v.feasible?'満たす':'満たさない'):'条件を満たす案なし'}</td><td>${v?v.rows.filter(r=>!r.feasible).map(r=>r.id).join('、')||'なし':'—'}</td></tr>`).join('')+'</tbody></table></div>'+`<p>${!result.reevaluated.feasible?'在庫条件を満たさないため、利益差の割合は比較しません。':result.gap===null?'最適利益が正でないため、利益差の割合は定義しません。':'基準案の利益は最適利益より'+fmt(100*result.gap)+'%低くなっています。'} 名目値は、この需要をすべて販売できると仮定した金額です。</p><p>全${result.oracle.candidates}候補を探索完了。在庫・幅の条件を満たす案${result.oracle.feasible_count}、同じ最大利益を得る案${result.oracle.ties.length}。</p>`;
if(x){const max=Math.max(1,...x.rows.map(v=>v.demand));$('bars').innerHTML+='<h3>需要の内訳（個／周期）</h3><p>緑＝商品自身の需要、茶＝流入需要</p>'+x.rows.filter(v=>v.k).map(v=>`<p>${v.id}：${fmt(v.direct)} ＋ ${fmt(v.transfer)}<br><span class="bar" style="width:${v.direct/max*60}%"></span><span class="bar required" style="width:${v.transfer/max*60}%"></span></p>`).join('');}
$('truncation').innerHTML=data.name==='T3'?(()=>{const raw=ReplenishmentModel.evaluate(data,[1,0]),r=raw.rows[0],clipped=data.items[0].f?Math.min(r.demand,r.stock/data.items[0].f):r.demand;return `<h3>別評価：需要を切り詰めると何が変わるか</h3><p>A1面の元需要${fmt(r.demand)}、切詰め後${fmt(clipped)}、切詰め後利益${fmt(clipped*data.items[0].p-data.items[0].c)}。元案は${raw.feasible?'実行可能':'実行不能'}。この切詰め値を元問題の実行可能利益として順位付けしません。</p>`;})():'';
